import{b as o,s as i}from"../auth-C3nl4jWx.js";/* empty css               */import"https://esm.sh/@supabase/supabase-js@2";const d=document.getElementById("admin-login-form"),n=document.getElementById("error-msg"),t=document.getElementById("submit-btn");d.addEventListener("submit",async a=>{a.preventDefault(),n.style.display="none",t.disabled=!0,t.textContent="ログイン中...";try{const e=await o({email:document.getElementById("email").value,password:document.getElementById("password").value}),{data:s}=await i.from("profiles").select("is_admin").eq("id",e.user.id).maybeSingle();if(!s||!s.is_admin)throw new Error("管理者権限がありません。");window.location.href="index.html"}catch(e){n.textContent=e.message==="Invalid login credentials"?"メールアドレスまたはパスワードが正しくありません。":e.message,n.style.display="block",t.disabled=!1,t.textContent="ログイン"}});
